class GreenLightState(LightState):
    def signal(self):
        print("Go!")

    def next(self, light):
        light.set_state(RedLightState())


class TrafficLight:
    def __init__(self):
        self.state = RedLightState()

    def set_state(self, state):
        self.state = state

    def signal(self):
        self.state.signal()

    def next(self):
        self.state.next(self)


