    @Override
    public void signal() { System.out.println("Go!"); }

    @Override
    public void next(TrafficLight light) { light.setState(new RedLightState()); }
}

class TrafficLight {
    private LightState state = new RedLightState();

    public void setState(LightState state) { this.state = state; }

    public void signal() { state.signal(); }
    public void next() { state.next(this); }
}

