#include <bits/stdc++.h>
using namespace std;

class TrafficLight;

class LightState {
public:
    virtual void signal() = 0;
    virtual void next(TrafficLight& light) = 0;
    virtual ~LightState() = default;
};

class TrafficLight {
    LightState* state;
public:
    TrafficLight(LightState* initial) : state(initial) {}

    void setState(LightState* newState) { state = newState; }

    void signal() { state->signal(); }
    void next() { state->next(*this); }
};

class RedLightState : public LightState {
public:
    void signal() override { cout << "Stop!" << endl; }
    void next(TrafficLight& light) override;
};

class GreenLightState : public LightState {
public:
    void signal() override { cout << "Go!" << endl; }
    void next(TrafficLight& light) override { light.setState(new RedLightState()); }
};

void RedLightState::next(TrafficLight& light) { light.setState(new GreenLightState()); }

int main() {
    RedLightState initial;
    TrafficLight trafficLight(&initial);

    // No if-else anywhere
    trafficLight.signal(); // delegates to current state
    trafficLight.next();   // switches to next state automatically
    return 0;
}

