class Order {
    private enum State {
        PENDING, PROCESSING, SHIPPED, DELIVERED
    }

    private State currentState = State.PENDING;
    private String orderId;

    public Order(String orderId) {
        this.orderId = orderId;
    }

    public void confirm() {
        switch (currentState) {
            case PENDING:
                System.out.println("Order " + orderId + " confirmed. Now processing.");
                currentState = State.PROCESSING;
                break;
            case PROCESSING:
                System.out.println("Order already being processed.");
                break;
            case SHIPPED:
                System.out.println("Order already shipped. Cannot confirm.");
                break;
            case DELIVERED:
                System.out.println("Order already delivered. Cannot confirm.");
                break;
        }
    }

    public void ship() {
        switch (currentState) {
            case PENDING:
                System.out.println("Cannot ship. Order not confirmed yet.");
                break;
            case PROCESSING:
                System.out.println("Order " + orderId + " shipped!");
                currentState = State.SHIPPED;
                break;
            case SHIPPED:
                System.out.println("Order already shipped.");
                break;
            case DELIVERED:
                System.out.println("Order already delivered. Cannot ship.");
                break;
        }
    }

    public void deliver() {
        switch (currentState) {
            case PENDING:
                System.out.println("Cannot deliver. Order not confirmed.");
                break;
            case PROCESSING:
                System.out.println("Cannot deliver. Order not shipped yet.");
                break;
            case SHIPPED:
                System.out.println("Order " + orderId + " delivered!");
                currentState = State.DELIVERED;
                break;
            case DELIVERED:
                System.out.println("Order already delivered.");
                break;
        }
    }

    public void cancel() {
        switch (currentState) {
            case PENDING:
            case PROCESSING:
                System.out.println("Order " + orderId + " cancelled.");
                currentState = State.PENDING;
                break;
            case SHIPPED:
                System.out.println("Cannot cancel. Order already shipped.");
                break;
            case DELIVERED:
                System.out.println("Cannot cancel. Order already delivered.");
                break;
        }
    }
}

public class Main {
    public static void main(String[] args) {
        Order order = new Order("ORD-001");
        order.ship();      // Cannot ship yet
        order.confirm();   // Confirmed
        order.ship();      // Shipped
        order.cancel();    // Cannot cancel
        order.deliver();   // Delivered
    }
}

