from enum import Enum


class State(Enum):
    PENDING = 1
    PROCESSING = 2
    SHIPPED = 3
    DELIVERED = 4


class Order:
    def __init__(self, order_id):
        self.current_state = State.PENDING
        self.order_id = order_id

    def confirm(self):
        if self.current_state == State.PENDING:
            print(f"Order {self.order_id} confirmed. Now processing.")
            self.current_state = State.PROCESSING
        elif self.current_state == State.PROCESSING:
            print("Order already being processed.")
        elif self.current_state == State.SHIPPED:
            print("Order already shipped. Cannot confirm.")
        elif self.current_state == State.DELIVERED:
            print("Order already delivered. Cannot confirm.")

    def ship(self):
        if self.current_state == State.PENDING:
            print("Cannot ship. Order not confirmed yet.")
        elif self.current_state == State.PROCESSING:
            print(f"Order {self.order_id} shipped!")
            self.current_state = State.SHIPPED
        elif self.current_state == State.SHIPPED:
            print("Order already shipped.")
        elif self.current_state == State.DELIVERED:
            print("Order already delivered. Cannot ship.")

    def deliver(self):
        if self.current_state == State.PENDING:
            print("Cannot deliver. Order not confirmed.")
        elif self.current_state == State.PROCESSING:
            print("Cannot deliver. Order not shipped yet.")
        elif self.current_state == State.SHIPPED:
            print(f"Order {self.order_id} delivered!")
            self.current_state = State.DELIVERED
        elif self.current_state == State.DELIVERED:
            print("Order already delivered.")

    def cancel(self):
        if self.current_state in (State.PENDING, State.PROCESSING):
            print(f"Order {self.order_id} cancelled.")
            self.current_state = State.PENDING
        elif self.current_state == State.SHIPPED:
            print("Cannot cancel. Order already shipped.")
        elif self.current_state == State.DELIVERED:
            print("Cannot cancel. Order already delivered.")


if __name__ == "__main__":
    order = Order("ORD-001")
    order.ship()      # Cannot ship yet
    order.confirm()   # Confirmed
    order.ship()      # Shipped
    order.cancel()    # Cannot cancel
    order.deliver()   # Delivered

