from abc import ABC, abstractmethod


class OrderState(ABC):
    @abstractmethod
    def confirm(self, order):
        pass

    @abstractmethod
    def ship(self, order):
        pass

    @abstractmethod
    def deliver(self, order):
        pass

    @abstractmethod
    def cancel(self, order):
        pass


class PendingState(OrderState):
    def confirm(self, order):
        print(f"Order {order.get_order_id()} confirmed. Now processing.")
        order.set_state(ProcessingState())

    def ship(self, order):
        print("Cannot ship. Order not confirmed yet.")

    def deliver(self, order):
        print("Cannot deliver. Order not confirmed yet.")

    def cancel(self, order):
        print(f"Order {order.get_order_id()} cancelled.")
        order.set_state(CancelledState())


class ProcessingState(OrderState):
    def confirm(self, order):
        print("Order already being processed.")

    def ship(self, order):
        print(f"Order {order.get_order_id()} shipped!")
        order.set_state(ShippedState())

    def deliver(self, order):
        print("Cannot deliver. Order not shipped yet.")

    def cancel(self, order):
        print(f"Order {order.get_order_id()} cancelled during processing.")
        order.set_state(CancelledState())


class ShippedState(OrderState):
    def confirm(self, order):
        print("Order already shipped.")

    def ship(self, order):
        print("Order already shipped.")

    def deliver(self, order):
        print(f"Order {order.get_order_id()} delivered successfully!")
        order.set_state(DeliveredState())

