    def ship(self, order):
        pass

    @abstractmethod
    def deliver(self, order):
        pass

    @abstractmethod
    def cancel(self, order):
        pass


class PendingState(OrderState):
    def confirm(self, order):
        print(f"Order {order.get_order_id()} confirmed. Now processing.")
        order.set_state(ProcessingState())

    def ship(self, order):
        print("Cannot ship. Order not confirmed yet.")

    def deliver(self, order):
        print("Cannot deliver. Order not confirmed yet.")

    def cancel(self, order):
        print(f"Order {order.get_order_id()} cancelled.")
        order.set_state(CancelledState())


