    def confirm(self, order):
        print("Order is cancelled. Cannot confirm.")

    def ship(self, order):
        print("Order is cancelled. Cannot ship.")

    def deliver(self, order):
        print("Order is cancelled. Cannot deliver.")

    def cancel(self, order):
        print("Order is already cancelled.")


