#include <bits/stdc++.h>
using namespace std;

class Order;

class OrderState {
public:
    virtual void confirm(Order& order) = 0;
    virtual void ship(Order& order) = 0;
    virtual void deliver(Order& order) = 0;
    virtual void cancel(Order& order) = 0;
    virtual ~OrderState() = default;
};

class Order {
    OrderState* currentState;
    string orderId;
public:
    Order(string orderId, OrderState* initial) : orderId(orderId), currentState(initial) {
        cout << "Order " << orderId << " created. State: Pending" << endl;
    }

    void setState(OrderState* state) { currentState = state; }

    string getOrderId() { return orderId; }

    void confirm() { currentState->confirm(*this); }
    void ship() { currentState->ship(*this); }
    void deliver() { currentState->deliver(*this); }
    void cancel() { currentState->cancel(*this); }
};

class DeliveredState : public OrderState {
public:
    void confirm(Order& order) override { cout << "Order already delivered." << endl; }
    void ship(Order& order) override { cout << "Order already delivered." << endl; }
    void deliver(Order& order) override { cout << "Order already delivered." << endl; }
    void cancel(Order& order) override { cout << "Cannot cancel. Order already delivered." << endl; }
};

class CancelledState : public OrderState {
public:
    void confirm(Order& order) override { cout << "Order is cancelled. Cannot confirm." << endl; }
    void ship(Order& order) override { cout << "Order is cancelled. Cannot ship." << endl; }
    void deliver(Order& order) override { cout << "Order is cancelled. Cannot deliver." << endl; }
    void cancel(Order& order) override { cout << "Order is already cancelled." << endl; }
};

class ShippedState : public OrderState {
public:
    void confirm(Order& order) override {
        cout << "Order already shipped." << endl;
    }

    void ship(Order& order) override {
        cout << "Order already shipped." << endl;
    }

    void deliver(Order& order) override {
        cout << "Order " << order.getOrderId() << " delivered successfully!" << endl;
        order.setState(new DeliveredState());
    }

    void cancel(Order& order) override {
        cout << "Cannot cancel. Order already shipped." << endl;
    }
};

class ProcessingState : public OrderState {
public:
    void confirm(Order& order) override {
        cout << "Order already being processed." << endl;
    }

    void ship(Order& order) override {
        cout << "Order " << order.getOrderId() << " shipped!" << endl;
        order.setState(new ShippedState());
    }

    void deliver(Order& order) override {
        cout << "Cannot deliver. Order not shipped yet." << endl;
    }

    void cancel(Order& order) override {
        cout << "Order " << order.getOrderId() << " cancelled during processing." << endl;
        order.setState(new CancelledState());
    }
};

class PendingState : public OrderState {
public:
    void confirm(Order& order) override {
        cout << "Order " << order.getOrderId() << " confirmed. Now processing." << endl;
        order.setState(new ProcessingState());
    }

    void ship(Order& order) override {
        cout << "Cannot ship. Order not confirmed yet." << endl;
    }

    void deliver(Order& order) override {
        cout << "Cannot deliver. Order not confirmed yet." << endl;
    }

    void cancel(Order& order) override {
        cout << "Order " << order.getOrderId() << " cancelled." << endl;
        order.setState(new CancelledState());
    }
};

int main() {
    Order order("ORD-001", new PendingState());

    cout << endl << "--- Normal Flow ---" << endl;
    order.ship();      // Rejected: not confirmed
    order.confirm();   // Pending → Processing
    order.ship();      // Processing → Shipped
    order.cancel();    // Rejected: already shipped
    order.deliver();   // Shipped → Delivered
    order.cancel();    // Rejected: already delivered

    cout << endl << "--- Cancel Flow ---" << endl;
    Order order2("ORD-002", new PendingState());
    order2.confirm();  // Pending → Processing
    order2.cancel();   // Processing → Cancelled
    order2.ship();     // Rejected: cancelled
    return 0;
}

