from abc import ABC, abstractmethod


# State Interface
class TrafficLightState(ABC):
    @abstractmethod
    def signal(self, light):
        pass

    @abstractmethod
    def next(self, light):
        pass


# Concrete States
class RedState(TrafficLightState):
    def signal(self, light):
        print("RED — Stop! Do not cross.")

    def next(self, light):
        print("Switching RED → GREEN")
        light.set_state(GreenState())


class GreenState(TrafficLightState):
    def signal(self, light):
        print("GREEN — Go! Safe to cross.")

    def next(self, light):
        print("Switching GREEN → YELLOW")
        light.set_state(YellowState())


class YellowState(TrafficLightState):
    def signal(self, light):
        print("YELLOW — Slow down. Prepare to stop.")

    def next(self, light):
        print("Switching YELLOW → RED")
        light.set_state(RedState())


# Context
class TrafficLight:
    def __init__(self):
        self.current_state = RedState()

    def set_state(self, state):
        self.current_state = state

    def signal(self):
        self.current_state.signal(self)

    def next(self):
        self.current_state.next(self)


# Client
if __name__ == "__main__":
    light = TrafficLight()

    for i in range(6):
        light.signal()
        light.next()
        print()

