#include <bits/stdc++.h>
using namespace std;

class TrafficLight;

// State Interface
class TrafficLightState {
public:
    virtual void signal(TrafficLight& light) = 0;
    virtual void next(TrafficLight& light) = 0;
    virtual ~TrafficLightState() = default;
};

// Context
class TrafficLight {
    TrafficLightState* currentState;
public:
    TrafficLight(TrafficLightState* initial) : currentState(initial) {}

    void setState(TrafficLightState* state) { currentState = state; }

    void signal() { currentState->signal(*this); }
    void next() { currentState->next(*this); }
};

// Concrete States
class YellowState : public TrafficLightState {
public:
    void signal(TrafficLight& light) override {
        cout << "YELLOW — Slow down. Prepare to stop." << endl;
    }

    void next(TrafficLight& light) override;
};

class GreenState : public TrafficLightState {
public:
    void signal(TrafficLight& light) override {
        cout << "GREEN — Go! Safe to cross." << endl;
    }

    void next(TrafficLight& light) override {
        cout << "Switching GREEN → YELLOW" << endl;
        light.setState(new YellowState());
    }
};

class RedState : public TrafficLightState {
public:
    void signal(TrafficLight& light) override {
        cout << "RED — Stop! Do not cross." << endl;
    }

    void next(TrafficLight& light) override {
        cout << "Switching RED → GREEN" << endl;
        light.setState(new GreenState());
    }
};

void YellowState::next(TrafficLight& light) {
    cout << "Switching YELLOW → RED" << endl;
    light.setState(new RedState());
}

// Client
int main() {
    RedState initial;
    TrafficLight light(&initial);

    for (int i = 0; i < 6; i++) {
        light.signal();
        light.next();
        cout << endl;
    }
    return 0;
}
